#!/usr/bin/env node

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { readdir } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { spawnSync } from "node:child_process";

const root = process.cwd();
const migrationsDir = join(root, "supabase", "migrations");
const seedFile = join(root, "supabase", "seed.sql");

function usage() {
  console.log(`Usage:
  npm run db:bundle -- [options]

Options:
  --from <prefix-or-file>   Start at a migration, for example 0031 or 0031_backfill_approved_visitor_records.sql
  --to <prefix-or-file>     End at a migration, for example 0032
  --include-seed            Append supabase/seed.sql after selected migrations
  --output <path>           Write to a custom path. Default: tmp/supabase-selected.sql
  --clipboard               Copy the generated SQL to the macOS clipboard
  --list                    Print available migrations and exit
  --help                    Show this help

Examples:
  npm run db:bundle
  npm run db:bundle -- --from 0031 --include-seed --clipboard
  npm run db:bundle -- --from 0029 --to 0032 --output tmp/registration-storage.sql
`);
}

function parseArgs(argv) {
  const options = {
    from: null,
    to: null,
    includeSeed: false,
    output: "tmp/supabase-selected.sql",
    clipboard: false,
    list: false,
    help: false,
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    switch (arg) {
      case "--from":
        options.from = argv[++index];
        break;
      case "--to":
        options.to = argv[++index];
        break;
      case "--include-seed":
        options.includeSeed = true;
        break;
      case "--output":
        options.output = argv[++index];
        break;
      case "--clipboard":
        options.clipboard = true;
        break;
      case "--list":
        options.list = true;
        break;
      case "--help":
      case "-h":
        options.help = true;
        break;
      default:
        throw new Error(`Unknown option: ${arg}`);
    }
  }

  return options;
}

async function getMigrationFiles() {
  if (!existsSync(migrationsDir)) {
    throw new Error(`Missing migrations directory: ${migrationsDir}`);
  }

  const files = (await readdir(migrationsDir))
    .filter((file) => /^\d{4}_.+\.sql$/.test(file))
    .sort((a, b) => a.localeCompare(b));

  if (files.length === 0) {
    throw new Error("No migration files found.");
  }

  return files;
}

function findBoundary(files, value, label) {
  if (!value) {
    return null;
  }

  const normalized = value.endsWith(".sql") ? value : null;
  const found = normalized
    ? files.find((file) => file === normalized)
    : files.find((file) => file.startsWith(`${value}_`) || file.startsWith(value));

  if (!found) {
    throw new Error(`Could not find ${label} migration: ${value}`);
  }

  return files.indexOf(found);
}

function buildSql(files, options) {
  const startIndex = findBoundary(files, options.from, "--from") ?? 0;
  const endIndex = findBoundary(files, options.to, "--to") ?? files.length - 1;

  if (startIndex > endIndex) {
    throw new Error("--from must be earlier than or equal to --to.");
  }

  const selected = files.slice(startIndex, endIndex + 1);
  const generatedAt = new Date().toISOString();
  const chunks = [
    `-- Generated by scripts/build-supabase-sql-bundle.mjs at ${generatedAt}`,
    "-- Paste this bundle into Supabase SQL Editor, or run the selected files one by one if an error needs isolation.",
    `-- Selected migrations: ${selected[0]} through ${selected[selected.length - 1]}`,
    "",
  ];

  for (const file of selected) {
    const path = join(migrationsDir, file);
    chunks.push(`-- ============================================================`);
    chunks.push(`-- ${file}`);
    chunks.push(`-- ============================================================`);
    chunks.push(readFileSync(path, "utf8").trimEnd());
    chunks.push("");
  }

  if (options.includeSeed) {
    if (!existsSync(seedFile)) {
      throw new Error(`Missing seed file: ${seedFile}`);
    }

    chunks.push("-- ============================================================");
    chunks.push("-- seed.sql");
    chunks.push("-- ============================================================");
    chunks.push(readFileSync(seedFile, "utf8").trimEnd());
    chunks.push("");
  }

  return {
    sql: `${chunks.join("\n")}\n`,
    selected,
  };
}

function copyToClipboard(sql) {
  const result = spawnSync("pbcopy", {
    input: sql,
    encoding: "utf8",
  });

  if (result.error || result.status !== 0) {
    throw new Error("Could not copy SQL to clipboard with pbcopy.");
  }
}

async function main() {
  const options = parseArgs(process.argv.slice(2));

  if (options.help) {
    usage();
    return;
  }

  const files = await getMigrationFiles();

  if (options.list) {
    for (const file of files) {
      console.log(file);
    }
    return;
  }

  const { sql, selected } = buildSql(files, options);
  const outputPath = resolve(root, options.output);
  mkdirSync(dirname(outputPath), { recursive: true });
  writeFileSync(outputPath, sql, "utf8");

  if (options.clipboard) {
    copyToClipboard(sql);
  }

  console.log(`Wrote ${selected.length} migration(s) to ${options.output}`);
  console.log(`First: ${selected[0]}`);
  console.log(`Last:  ${selected[selected.length - 1]}`);

  if (options.includeSeed) {
    console.log("Included: supabase/seed.sql");
  }

  if (options.clipboard) {
    console.log("Copied SQL bundle to clipboard.");
  }
}

main().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
